INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (61, 1, '설명에 해당하는 스토리지 고르기: Ceph', '여러 서버의 디스크를 묶어 **하나의 분산 스토리지**처럼 쓰게 해 주는 오픈소스 소프트웨어입니다. **블록, 파일, 오브젝트(S3 호환)** 세 가지 형태를 하나의 클러스터로 제공하고, 레드햇이 인수해 RHCS 라는 이름으로 지원판을 냅니다. 무엇일까요?', '실제로 데이터를 저장하는 쪽입니다. 플랫폼별 연결 계층(ODF, Cinder)이 아닙니다.', NULL, NULL, '[]', 'choice', '["Ceph", "Cinder", "ODF", "Neutron"]', 0, '**Ceph** 는 실제로 데이터를 분산 저장하는 스토리지 시스템입니다. OCP(컨테이너)와 OpenStack(VM) 양쪽에서 백엔드로 쓰기 때문에 "Ceph 를 쓴다"는 말만으로는 컨테이너 환경인지 VM 환경인지 알 수 없고, 어떤 연결 계층(ODF 또는 Cinder)을 거치는지 봐야 합니다.', NULL, NULL, NULL, NULL),
  (61, 2, '설명에 해당하는 스토리지 고르기: ODF', 'OCP 클러스터 안에서 **Ceph 를 배포하고 운영해 주는 오퍼레이터**로, Pod 가 쓸 영구 스토리지(PersistentVolume)를 제공합니다. 예전 이름은 OCS 였습니다. 무엇일까요?', '컨테이너(OCP) 쪽 연결 계층입니다.', NULL, NULL, '[]', 'choice', '["Ceph 자체", "ODF (OpenShift Data Foundation)", "Cinder", "Keystone"]', 1, '**ODF** 는 Ceph 를 OCP 위에 편하게 얹는 배포·관리 계층입니다. RHOV 가 KVM 을 OCP 위에 얹은 것과 같은 패턴으로, 밑바탕 기술(Ceph)은 그대로이고 쿠버네티스 방식으로 쓰게 해 줍니다.', NULL, NULL, NULL, NULL),
  (61, 3, '설명에 해당하는 스토리지 고르기: Cinder', 'OpenStack 에서 **VM 에 블록 스토리지(가상 디스크)** 를 만들어 붙여 주는 서비스입니다. Nova 가 VM 을 만들면 그 VM 이 쓸 볼륨을 만들어 연결합니다. 무엇일까요?', '컨테이너가 아니라 VM 환경 전용입니다.', NULL, NULL, '[]', 'choice', '["ODF", "Neutron", "Cinder", "OVN-Kubernetes"]', 2, '**Cinder** 는 OpenStack(VM)용 블록 스토리지 서비스입니다. ODF 와 대응하는 역할이지만 ODF 는 Pod(OCP) 전용, Cinder 는 VM(OpenStack) 전용입니다. Neutron 은 네트워크, OVN-Kubernetes 는 OCP 네트워크입니다.', NULL, NULL, NULL, NULL),
  (61, 4, 'Cinder 가 직접 데이터를 저장하는지 알기', 'Cinder 에 대한 설명으로 알맞은 것은 무엇일까요?', '"이 VM 에 100GB 볼륨을 만들어서 붙여줘" 를 누가 처리하고, 실제 저장은 누가 할까요?', NULL, NULL, '[]', 'choice', '["Cinder 가 자체 디스크에 모든 데이터를 직접 저장한다", "Cinder 는 네트워크 패킷을 전달한다", "Cinder 는 VM 이미지를 빌드한다", "Cinder 는 요청을 받아 백엔드(주로 Ceph)에 전달하고 관리하는 **API 계층**이며, 실제 저장은 백엔드가 한다"]', 3, 'Cinder 는 **관리·연결 계층**이고 데이터를 직접 저장하지 않습니다. 실제 저장은 백엔드(주로 Ceph)가 합니다. 그래서 "VM 에 디스크가 안 붙는다"는 문제는 Cinder(요청 처리)와 Ceph(저장) 어느 쪽 문제인지 나눠서 봐야 합니다.', NULL, NULL, NULL, NULL),
  (61, 5, '"스토리지가 안 붙는다" 보고를 받았을 때 먼저 할 일', '"스토리지가 안 붙는다"는 보고가 들어왔습니다. 원인을 좁히기 위해 **가장 먼저** 확인할 것은 무엇일까요?', '같은 Ceph 를 쓰더라도 연결 계층이 환경마다 다릅니다.', NULL, NULL, '[]', 'choice', '["문제가 난 곳이 **VM 환경(OpenStack, Cinder)인지 컨테이너 환경(OCP, ODF)인지**", "서버의 모니터 크기", "사용자의 이름", "네트워크 선의 색깔"]', 0, '저장소는 하나(Ceph)이고 연결 계층이 둘(Cinder, ODF)이라서, 환경을 먼저 구분해야 어느 계층의 문제인지 좁힐 수 있습니다. 컨테이너면 ODF·PV 쪽, VM 이면 Cinder 쪽부터 봅니다.', NULL, NULL, NULL, NULL),
  (61, 6, '설명에 해당하는 네트워크 고르기: OVN-Kubernetes', 'OCP 클러스터의 기본 **CNI 플러그인**으로, Pod 에 IP 를 할당하고 다른 노드의 Pod 와도 통신하도록 오버레이 네트워크를 구성하며 NetworkPolicy 를 담당합니다. 무엇일까요?', '컨테이너(OCP) 쪽 네트워크 연결 계층입니다.', NULL, NULL, '[]', 'choice', '["Neutron", "OVN-Kubernetes", "Cinder", "Ceph"]', 1, '**OVN-Kubernetes** 는 OCP 의 CNI 로, OVN 엔진을 쿠버네티스 API(Pod, Service, NetworkPolicy)에 맞게 연결합니다. Docker 의 `docker0` 브리지가 한 호스트 안에서만 컨테이너를 묶는 것과 달리, 노드가 달라도 Pod 끼리 통신하게 합니다.', NULL, NULL, NULL, NULL),
  (61, 7, 'Neutron 이 하는 일 알기', 'OpenStack 의 **Neutron** 이 하는 일로 알맞은 것은 무엇일까요?', 'Nova 는 VM 을, Cinder 는 디스크를 만듭니다. Neutron 은 무엇을 만들까요?', NULL, NULL, '[]', 'choice', '["VM 이 쓸 디스크 볼륨을 만든다", "VM 의 CPU 와 메모리를 할당한다", "VM 이 통신할 **가상 네트워크, 서브넷, 라우터, 보안 그룹(방화벽 규칙)** 을 만들고 연결한다", "사용자 로그인과 권한을 확인한다"]', 2, 'Neutron 은 OpenStack 의 **네트워킹** 서비스입니다. 최신 RHOSP 는 Neutron 의 드라이버로 OVN 을 씁니다. (디스크는 Cinder, 컴퓨트(VM 생성)는 Nova, 인증은 Keystone 이 맡습니다.)', NULL, NULL, NULL, NULL),
  (61, 8, 'OVN 과 Neutron·OVN-Kubernetes 의 관계 알기', '**OVN(Open Virtual Network)** 과 Neutron, OVN-Kubernetes 의 관계로 알맞은 것은 무엇일까요?', '스토리지에서 "저장소 하나, 연결 계층 둘" 이었던 구도가 네트워킹에서도 반복됩니다.', NULL, NULL, '[]', 'choice', '["OVN 은 Neutron 의 이전 버전 이름이다", "Neutron 과 OVN-Kubernetes 는 서로 전혀 관계없는 별개의 기술이다", "OVN-Kubernetes 는 VM 용이고 Neutron 은 컨테이너용이다", "OVN 은 브리지·라우터·보안 규칙을 소프트웨어로 정의하는 **공통 기반 엔진**이고, Neutron(VM)과 OVN-Kubernetes(Pod)는 각 플랫폼에서 그 엔진을 쓰는 **연결 계층**이다"]', 3, '스토리지에서 Ceph 가 하나이고 ODF/Cinder 가 연결 계층이었던 것과 같이, 네트워킹도 **OVN 이라는 엔진 하나**를 두 플랫폼이 각자 연결 계층으로 쓰는 구도입니다. 그래서 로그나 트러블슈팅에서 두 환경에 OVN 이라는 이름이 공통으로 나옵니다.', NULL, NULL, NULL, NULL),
  (61, 9, 'OpenStack 에서 VM 이 쓸 수 있게 되기까지 순서 놓기', '사용자가 OpenStack 에 VM 을 요청했을 때, **쓸 수 있는 VM** 이 되기까지 일어나는 일을 **앞에서 뒤로** 놓으세요.', '요청 확인 → 인스턴스 → 네트워크 → 디스크 → 전달 순서입니다.', NULL, NULL, '[]', 'order', '["Cinder 가 VM 에 디스크 볼륨을 만들어 연결한다", "사용자가 VM 을 요청하고 인증과 권한을 확인한다", "Nova 가 VM 인스턴스(CPU, 메모리)를 만든다", "Neutron 이 네트워크 인터페이스를 붙이고 IP 와 보안 그룹을 설정한다", "모든 준비가 끝난 VM 이 사용 가능한 상태로 전달된다"]', NULL, '**요청·인증 → Nova(인스턴스) → Neutron(네트워크) → Cinder(디스크) → 사용 가능한 VM** 순서입니다. VM 만 딱 만드는 것이 아니라 접속하고 데이터를 저장할 수 있는 상태까지 갖춰서 내주는 것이 프로비저닝입니다. (실제로는 일부가 병렬로 일어나지만 개념 순서로 이해하면 됩니다.)', '[1, 2, 3, 0, 4]', NULL, NULL, NULL),
  (61, 10, '프로비저닝의 의미 알기', '"OpenStack 이 VM 을 **프로비저닝**한다"에서 프로비저닝은 단순한 "생성"과 무엇이 다를까요?', '만들고 끝이 아니라 "바로 쓸 수 있게" 넘겨주는 데까지입니다.', NULL, NULL, '[]', 'choice', '["자원 할당뿐 아니라 네트워크 연결, 이미지 부팅, 접근 권한 설정까지 마쳐서 **바로 쓸 수 있는 상태로 넘겨주는 전체 흐름**을 가리킨다", "VM 을 삭제하는 것을 뜻한다", "VM 의 이름만 정하는 것을 뜻한다", "생성과 완전히 같은 말이다"]', 0, '프로비저닝은 "만들어서 → 설정하고 → 바로 쓸 수 있게 넘겨주는" 전체 과정입니다. 생성은 그 일부일 뿐입니다. OpenStack 이 "코드와 API 로 프로비저닝한다"는 말은 요청만으로 필요한 자원이 자동으로 할당·설정되어 나온다는 뜻입니다.', NULL, NULL, NULL, NULL),
  (61, 11, '테넌트와 멀티테넌트 알기', '하나의 OpenStack 클러스터에서 여러 팀이 각자 **프로젝트(테넌트)** 를 갖고 VM 을 띄웁니다. 테넌트 사이의 관계로 알맞은 것은 무엇일까요?', '한 건물에 입주한 여러 회사를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["모든 팀이 서로의 VM 을 자유롭게 지울 수 있다", "같은 물리 서버를 쓸 수 있어도 **네트워크가 분리**되고, 각자 **쿼터(할당량)** 만큼만 쓰며, 자기 프로젝트 안에서만 VM 을 만들고 지울 수 있다", "한 클러스터에는 테넌트를 하나만 둘 수 있다", "테넌트마다 물리 서버를 따로 사야 한다"]', 1, '**테넌트**는 공유 인프라를 나눠 쓰는 독립된 사용자 단위(회사, 팀, 고객)입니다. OpenStack 의 멀티테넌시는 네트워크 격리, 프로젝트별 쿼터, 프로젝트 안에서만 유효한 권한으로 구현됩니다. 이 셀프서비스 멀티테넌트 IaaS 가 OpenStack 의 목표이고 vCloud Director 가 VMware 쪽 대응입니다.', NULL, NULL, NULL, NULL),
  (61, 12, 'Proxmox 와 OpenStack 의 규모 차이 알기', 'Proxmox VE 가 OpenStack 보다 더 안정적으로 **느껴지는** 이유로 알맞은 것은 무엇일까요?', '제품의 "결함 차이"가 아니라 "풀려는 문제의 규모 차이" 입니다.', NULL, NULL, '[]', 'choice', '["Proxmox 가 OpenStack 의 후속 버전이라서", "OpenStack 은 VM 을 만들 수 없어서", "OpenStack 은 수백~수천 노드의 **멀티테넌트 대규모 클라우드**를 목표로 여러 독립 서비스와 메시지 큐·DB 로 구성되어 장애 지점이 많고, Proxmox 는 노드 몇 대를 단순하게 관리하는 것이 목표라 구조가 단순하다", "Proxmox 는 하이퍼바이저를 쓰지 않아서"]', 2, '"Proxmox 는 문제없고 OpenStack 은 문제 있다"가 아니라 **규모와 목적의 차이**입니다. Proxmox 는 KVM(VM)과 LXC(컨테이너)를 웹 UI 하나로 관리하는 레드햇도 VMware 도 아닌 제3의 진영입니다. 여러 팀에 독립된 네트워크·쿼터를 셀프서비스로 제공해야 한다면 OpenStack 이 맞고, 노드 몇 대면 Proxmox 가 단순합니다.', NULL, NULL, NULL, NULL),
  (61, 13, '저장소 하나, 연결 계층 둘 구도 정리하기', '지금까지 배운 스토리지 구도를 한 줄로 정리하면 무엇일까요?', '컨테이너(OCP)용과 VM(OpenStack)용 연결 계층이 각각 있습니다.', NULL, NULL, '[]', 'choice', '["ODF 와 Cinder 는 둘 다 Ceph 를 대체하는 별도 저장소이다", "Ceph 는 컨테이너 전용이고 Cinder 는 VM 전용 저장소이다", "ODF 는 VM 용, Cinder 는 Pod 용이다", "**Ceph 하나**(실제 저장)를 **컨테이너 환경은 ODF 로, VM 환경은 Cinder 로** 연결해서 쓴다"]', 3, '핵심은 "저장소는 하나, 연결 계층이 둘"입니다. 네트워킹도 같은 구도(OVN 하나, Neutron·OVN-Kubernetes 둘)이고, 이 반복되는 패턴을 알아채면 처음 보는 이름이 나와도 어느 층 이야기인지 금방 구분할 수 있습니다.', NULL, NULL, NULL, NULL);
